   if(requestResearch){researchOptions({...requestResearch,enabled:true},requestResearch,settings.mode==='local',lang==='ar');if(settings.provider!=='ollama')throw Error(lang==='ar'?'البحث داخل المحادثة يتطلب النموذج المحلي. اختره من الإعدادات دون إرسال هذا الطلب إلى السحابة.':'Research in conversation requires the local model. Select it in settings before sending.');requestRetrieval.use_files=requestResearch.scopes.includes('files');requestRetrieval.use_knowledge=requestResearch.scopes.some(scope=>scope==='knowledge'||scope==='web');}
