     if(options.edit_message_id){const at=messages.findIndex(m=>m.id===options.edit_message_id);setMessages([...messages.slice(0,Math.max(at,0)),{id:'edited',role:'user',content,status:'complete',retrieval_options:retrievalOptions},assistant]);}
     else if(options.retry_message_id){const at=messages.findIndex(m=>m.id===options.retry_message_id);setMessages([...messages.slice(0,Math.max(at,0)),assistant]);}
